  FT["PH-H3446"] = {"id":"PH-H3446","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4244_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在卡加延省设立海洋渔业示范站并授权为此拨款的法案","en":"An Act Establishing a Marine Fisheries Demonstration Station in the Province of Cagayan and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Marine Fisheries Demonstration Station in the Province of Cagayan and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Trạm Trình diễn Thủy sản Marine tại Tỉnh Cagayan, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งสถานีสาธิตประมง Marine ในจังหวัด Cagayan และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Stasiun Percontohan Perikanan Marine di Provinsi Cagayan, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Stesen Demonstrasi Perikanan Marine di Wilayah Cagayan, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 4244","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4244_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3446-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established and maintained under the supervision of the Commissioner of Fisheries a marine fisheries demonstration station in any suitable site in the Province of Cagayan."}},{"id":"PH-H3446-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of three hundred fifty thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, to carry into effect the purpose of this Act during the fiscal year ending June thirtieth, nineteen hundred and sixty-six. Thereafter, the necessary amount for the purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3446-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a Marine Fisheries Demonstration Station in the Province of Cagayan and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3447"] = {"id":"PH-H3447","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4245_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在罗哈斯市设立家庭工业学校，名称为菲律宾工匠学校，并授权为此拨款的法案","en":"An Act Providing for the Establishment of a School for Home Industries in the City of Roxas, to be Known as the School for Philippine Craftsmen, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a School for Home Industries in the City of Roxas, to be Known as the School for Philippine Craftsmen, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4245","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4245_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3447-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision and administration of the Director of Vocational Education, a school for home industries in the City of Roxas, to be known as the School for Philippine Craftsmen."}},{"id":"PH-H3447-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education is hereby authorized to organize the curricular instruction in the said school, to determine its location within the City of Roxas, and to issue rules and regulations necessary to carry out the purposes of this Act."}},{"id":"PH-H3447-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of three hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said school, including the purchase of a site, for the fiscal year nineteen hundred sixty-four to nineteen hundred sixty-five. Thereafter, such sum as may be needed for the operation and maintenance of the said school shall be included in the annual General Appropriations Act."}},{"id":"PH-H3447-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a School for Home Industries in the City of Roxas, to be Known as the School for Philippine Craftsmen, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3448"] = {"id":"PH-H3448","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4246_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在卡加延-德奥罗市Malasag设立动物繁育站并授权为此拨款的法案","en":"An Act to Establish an Animal Breeding Station in Malasag, Cagayan De Oro City, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Establish an Animal Breeding Station in Malasag, Cagayan De Oro City, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4246","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4246_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3448-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Animal Industry, a breeding station in Malasag, Cagayan de Oro City."}},{"id":"PH-H3448-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of fifty thousand pesos is authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, to be expended by the Director of Animal Industry, subject to the approval of the Secretary of Agriculture and Natural Resources, for the purchase of breeding animals; for the purchase of supplies and materials; for the construction of buildings, sheds, corrals and other structures; for the establishment of water system; for salaries and wages, and for other expenses as may be necessary to carry out the purposes of this Act for the fiscal year ending June thirty, nineteen hundred sixty-six. Such sums as may be necessary for the operation and maintenance of the said breeding station in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H3448-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish an Animal Breeding Station in Malasag, Cagayan De Oro City, and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3449"] = {"id":"PH-H3449","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4247_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将东米萨米斯中学改设为国立中学，名称为东米萨米斯总综合中学，并授权为此拨款的法案","en":"An Act Converting the Misamis Oriental High School into a National High School to be Known as the Misamis Oriental General Comprehensive High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting the Misamis Oriental High School into a National High School to be Known as the Misamis Oriental General Comprehensive High School, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật chuyển đổi Misamis Oriental High School thành Misamis Oriental General Comprehensive High School","th":"พระราชบัญญัติเปลี่ยนสถานะ Misamis Oriental High School เป็น Misamis Oriental General Comprehensive High School","id":"Undang-Undang mengubah Misamis Oriental High School menjadi Misamis Oriental General Comprehensive High School","ms":"Akta menukar Misamis Oriental High School kepada Misamis Oriental General Comprehensive High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4247","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4247_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3449-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Misamis Oriental High School is hereby converted into a national high school, to be known as the Misamis Oriental General Comprehensive High School. Comprehensive curriculum which includes both academic and the industrial arts and handicraft courses shall be offered. The Secretary of Education is hereby empowered to reorganize the said school accordingly.\nUpon organization of the Misamis Oriental General Comprehensive High School, the assets, liabilities, personnel, equipment and records of the Misamis Oriental High School shall stand transferred to the Misamis Oriental General Comprehensive High School."}},{"id":"PH-H3449-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the said school in addition to its matriculation and tuition fees, and other revenues."}},{"id":"PH-H3449-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Misamis Oriental High School into a National High School to be Known as the Misamis Oriental General Comprehensive High School, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3450"] = {"id":"PH-H3450","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4248_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将奎松省迪拉萨格市镇区的德卡巴桑、德尼奥格、迪亚吉安与迪拉吉迪小村改设为各自独立的村的法案","en":"An Act Converting the Sitios of Decabasan, Deniog, Diagyan and Dilaguidi in the Municipal District of Dilasag, Province of Quezon, into Distinct and Independent Barrios","orig":"An Act Converting the Sitios of Decabasan, Deniog, Diagyan and Dilaguidi in the Municipal District of Dilasag, Province of Quezon, into Distinct and Independent Barrios"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4248","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4248_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3450-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Decabasan, Deniog, Diagyan and Dilaguidi in the Municipal District of Dilasag, Province of Quezon, are hereby converted into distinct and independent barrios, to be known as the Barrios of Decabasan, Deniog, Diagyan and Dilaguidi, respectively."}},{"id":"PH-H3450-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Sitios of Decabasan, Deniog, Diagyan and Dilaguidi in the Municipal District of Dilasag, Province of Quezon, into Distinct and Independent Barrios","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3451"] = {"id":"PH-H3451","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4249_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"规定为奎松省2 Additional 省立 Fiscals，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act to Provide Two Additional Provincial Fiscals for the Province of Quezon, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act to Provide Two Additional Provincial Fiscals for the Province of Quezon, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4249","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4249_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3451-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provisions of Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant fiscals in the Province of Quezon, is further amended to read as follows:\n\"Quezon, seven assistant provincial fiscals.\""}},{"id":"PH-H3451-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide Two Additional Provincial Fiscals for the Province of Quezon, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3452"] = {"id":"PH-H3452","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4250_1965.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"为菲律宾大学大地测量工程学习提供奖学金并授权拨款的法案","en":"An Act to Provide Scholarships for the Study of Geodetic Engineering in the University of the Philippines, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Provide Scholarships for the Study of Geodetic Engineering in the University of the Philippines, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4250","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4250_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3452-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Board of Regents of the University of the Philippines is hereby authorized to grant scholarships to Filipino citizens who desire to study geodetic engineering in the College of Engineering of the University of the Philippines, and such scholarships shall be granted in accordance with the following principles:\n(a) The scholarships shall be granted only to bright and deserving students who shall be selected through competitive examinations;\n(b) The scholarships may include living expenses, registration fees, matriculation fees and cost of books, instruments and other materials required in the study of geodetic engineering; and\n(c) The scholarships may be extended as an absolute grant to the scholar provided that he agrees to be employed in the government service for a certain number of years as may be determined by the Board of Regents; or it may be granted as a loan to be paid by the scholar out of his salary or earnings, without interest, after the scholarship is terminated. Payments collected on scholarships granted under this Act on a loan basis shall accrue to the Geodetic Scholarship Engineering Fund hereinafter constituted."}},{"id":"PH-H3452-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Board of Regents of the University of the Philippines shall promulgate such rules and regulations as may be necessary to carry into effect the provisions of this Act."}},{"id":"PH-H3452-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby authorized to be appropriated annually for a period of ten years, in lieu of the funds being appropriated for the Bureau of Lands government trainees studying in the University of the Philippines, out of any funds in the National Treasury not otherwise appropriated, the sum of seventy-five thousand pesos to constitute the Geodetic Engineering Scholarship Fund and to carry into effect the purposes of this Act."}},{"id":"PH-H3452-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All laws, executive orders, rules and regulations, or parts thereof in conflict with the provisions of this Act, are hereby repealed or amended accordingly."}},{"id":"PH-H3452-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide Scholarships for the Study of Geodetic Engineering in the University of the Philippines, and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3453"] = {"id":"PH-H3453","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4251_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Baggao市","en":"An Act Establishing an Agricultural High School at Tallang in the Municipality of Baggao, Province of Cagayan, to be Known as Baggao Agricultural High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing an Agricultural High School at Tallang in the Municipality of Baggao, Province of Cagayan, to be Known as Baggao Agricultural High School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 4251","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4251_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3453-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational Education, an agricultural high school at Tallang, Municipality of Baggao, Province of Cagayan to be known as Baggao Agricultural High School."}},{"id":"PH-H3453-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school for the fiscal year nineteen hundred sixty-six. Thereafter, the necessary sum for the operation and maintenance of said high school shall be included in the annual General Appropriations Act."}},{"id":"PH-H3453-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49"};
