  FT["PH-H3503"] = {"id":"PH-H3503","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4301_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在莱特省Tabango市镇设立菲律宾工匠学校，名称为Tabango职业学校，并授权为此拨款的法案","en":"An Act to Establish a School for Philippine Craftsmen in the Municipality of Tabango, Province of Leyte, to be Known as Tabango Vocational School, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Establish a School for Philippine Craftsmen in the Municipality of Tabango, Province of Leyte, to be Known as Tabango Vocational School, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4301","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4301_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3503-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A school of the Polangui School for Philippine Craftsmen type is hereby established in the Municipality of Tabango, Province of Leyte, to be known as Tabango Vocational School."}},{"id":"PH-H3503-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education is authorized to organize the curricular instruction of said school and he shall have the power to issue rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H3503-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred sixty-six. Thereafter, the sums necessary therefor shall be included in the annual General Appropriations Act."}},{"id":"PH-H3503-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish a School for Philippine Craftsmen in the Municipality of Tabango, Province of Leyte, to be Known as Tabango Vocational School, and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3504"] = {"id":"PH-H3504","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4302_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在莱特省比利兰分省Cabucgayan市镇设立国立工艺学校，名称为Cabucgayan国立工艺学校，并授权为此拨款的法案","en":"An Act to Establish a National School of Arts and Trades in the Municipality of Cabucgayan, Sub-Province of Biliran, Province of Leyte, to be Known as Cabucgayan National School of Arts and Trades, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Establish a National School of Arts and Trades in the Municipality of Cabucgayan, Sub-Province of Biliran, Province of Leyte, to be Known as Cabucgayan National School of Arts and Trades, and to Authorize the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Trường Nghệ thuật và Thương mại Quốc gia tại Đô thị Cabucgayan, Tỉnh Biliran, Tỉnh Leyte với tên gọi Trường Nghệ thuật và Thương mại Cabucgayan Quốc gia, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงเรียนศิลปะและหัตถกรรมแห่งชาติ ในเทศบาล Cabucgayan จังหวัด Biliran จังหวัด Leyte ในชื่อ โรงเรียนศิลปะและหัตถกรรม Cabucgayan แห่งชาติ และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Sekolah Seni dan Keterampilan Nasional di Kotamadya Cabucgayan, Provinsi Biliran, Provinsi Leyte dengan nama Sekolah Seni dan Keterampilan Cabucgayan Nasional, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Sekolah Seni dan Pertukangan Kebangsaan di Perbandaran Cabucgayan, Wilayah Biliran, Wilayah Leyte dengan nama Sekolah Seni dan Pertukangan Cabucgayan Kebangsaan, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 4302","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4302_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3504-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established a national school of arts and trades in the Municipality of Cabucgayan, Sub-Province of Biliran, Province of Leyte, to be known as Cabucgayan National School of Arts and Trades."}},{"id":"PH-H3504-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education is authorized to organize the curricular instruction in said school and he shall have the power to issue rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H3504-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred sixty-six. Thereafter, the sums necessary therefor shall be included in the annual General Appropriations Act."}},{"id":"PH-H3504-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish a National School of Arts and Trades in the Municipality of Cabucgayan, Sub-Province of Biliran, Province of Leyte, to be Known as Cabucgayan National School of Arts and Trades, and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3505"] = {"id":"PH-H3505","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4303_1965.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"规定在巴拉望省普林塞萨港市镇设立师范学院，名称为巴拉望师范学院，规定董事会及其职责并授权为此拨款的法案","en":"An Act Providing for the Establishment of a Teacher's College in the Municipality of Puerto Princesa, Province of Palawan, to be Known as Palawan Teachers' College, Providing for a Board of Trustees, Defining the Board's Responsibilities and Duties, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Teacher's College in the Municipality of Puerto Princesa, Province of Palawan, to be Known as Palawan Teachers' College, Providing for a Board of Trustees, Defining the Board's Responsibilities and Duties, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Cao đẳng Teacher's tại Thị trấn Puerto Princesa, Tỉnh Palawan với tên gọi Cao đẳng Palawan Teachers, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งวิทยาลัย Teacher's ในเทศบาล Puerto Princesa จังหวัด Palawan ในชื่อวิทยาลัย Palawan Teachers และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Sekolah Tinggi Teacher's di Kotamadya Puerto Princesa, Provinsi Palawan dengan nama Sekolah Tinggi Palawan Teachers, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Kolej Teacher's di Perbandaran Puerto Princesa, Wilayah Palawan dengan nama Kolej Palawan Teachers, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4303","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4303_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3505-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A teachers’ college is hereby established in the Municipality of Puerto Princesa, Province of Palawan, to be known as Palawan Teachers’ College which shall offer four-year courses leading to the degrees of Bachelor of Science in Elementary Education and Bachelor of Science in Education, and graduate courses leading to the degrees of Master of Arts and Master of Science in Education."}},{"id":"PH-H3505-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The purpose of the said college shall be to provide professional and technical instruction, with special provisions for the non-Christian tribes in the Province of Palawan, and for progressive leadership in the field of elementary and secondary education."}},{"id":"PH-H3505-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The head of the college shall be known as the President of the Palawan Teachers’ College. He shall be appointed by the President of the Philippines upon the recommendation of the Board of Trustees, subject to the confirmation of the Commission on Appointments. The powers and duties of the President of the College, in addition to those specifically provided for in this Act, shall be those usually pertaining to the office of the president of a college."}},{"id":"PH-H3505-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The government of said college is hereby vested in a Board of Trustees of the Palawan Teachers’ College. The Board of Trustees shall be composed of the Secretary of Education, who shall be ex-officio Chairman of the Board, the Chairman of the Committee on Education of the Senate, the Chairman of the Committee on Education of the House of Representatives, the Director of Vocational Education, the President of the College, and the President of the Palawan Teachers’ College Alumni Association, as members.\nMembers of the Board shall serve without compensation, other than actual and necessary expenses incurred either in attendance upon meetings of the Board or upon other official business authorized by resolution of the Board."}},{"id":"PH-H3505-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Board of Trustees shall have the following powers and duties, in addition to its general powers of administration:\n(a) To receive and appropriate to the ends specified by law such sums as may be provided by law for the support of the college;\n(b) To confer the degrees of Bachelor of Science in Elementary Education, Bachelor of Science in Education, Master of Arts, and Master of Science in Education, to successful candidates for graduation;\n(c) To appoint, on the recommendation of the President of the College, instructors, professors, lecturers, and other employees of the college; to fix their compensation, hours of service and such other duties and conditions as it may deem proper; to grant to them in its discretion, leave of absence under such regulations as it may promulgate, any other provisions of law notwithstanding, and to remove them for cause after an investigation and hearing shall have been had;\n(d) To approve the curricula and rules of discipline drawn up by the College Council as hereinafter provided;\n(e) To fix the tuition fees required of students, as well as matriculation fees, graduation fees, fees for laboratory courses, and all special fees, and to remit the same in special cases;\n(f) To provide fellowships for faculty members and scholarships to students showing special evidence of merit;\n(g) To provide rules for its own government, and to enact for the government of the College such general ordinances and regulations, not contrary to law, as are consistent with the purposes of the College, as defined in Section two of this Act;\n(h) To receive in trust legacies, gifts and donations of real and personal property of all kinds and to administer the same for the benefit of the College or for aid to any student, in accordance with the discretions and instructions of the donor, and, in default thereof, in such manner as the Board of Trustees may in its discretion determine."}},{"id":"PH-H3505-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members. All processes against the Board of Trustees shall be served on the president or secretary thereof."}},{"id":"PH-H3505-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"On or before the fifteenth of June of each year, the Board of Trustees shall file with the President of the Philippines a detailed report, setting forth the progress, condition, and needs of the College."}},{"id":"PH-H3505-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"There shall be a College Council consisting of the President of the College and all instructors and professors of the college. The Council shall have the power to prescribe the curricula and rules of discipline, subject to the approval of the Board of Trustees. It shall fix the requirements for admission to the College, as well as for graduation and the receiving of a degree. The Council alone shall have the power to recommend students or others to be recipients of degrees. Through its president or committee, it shall have disciplinary power over the students within the limits prescribed by the rules of discipline approved by the Board of Trustees."}},{"id":"PH-H3505-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The body of instructors and professors of the College shall constitute the faculty of the College, with the President of the College as the presiding officer. In the appointment of professors or instructors of the College, no religious test shall be applied, nor shall the religious opinions or affiliations of the faculty of the College be made a matter of examination or inquiry: Provided, However, That no instructor or professor in the college shall inculcate sectarian tenets in any of the teachings, nor attempt either directly or indirectly, under penalty of dismissal by the Board of Trustees, to influence students of attendants at the College for or against any particular church or religious sect."}},{"id":"PH-H3505-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Professors and other regular instructors in the College shall be exempt as such from any civil service examinations or regulations as a requisite to appointment."}},{"id":"PH-H3505-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"There shall be a secretary of the College, appointed by the Board of Trustees. He shall be the secretary of such Board and also of the College, and shall keep such records of the college as may be designated by the Board."}},{"id":"PH-H3505-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Heads of bureaus or offices of the National Government are hereby authorized to loan or transfer, upon request of the President of the College, such apparatus or supplies as may be needed by the College, and to detail employees for duty therein, when in the judgment of the head of the bureau or office such supplies or employees can be spared without serious detriment to the public service."}},{"id":"PH-H3505-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The President of the College, with the cooperation of the Division Superintendent of Schools of Palawan, may use one or more of the elementary schools in the Province of Palawan as training or laboratory schools of the college."}},{"id":"PH-H3505-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Salaries of the personnel shall be adjusted at the discretion of the Board of Trustees of said college without the amount available for appropriation."}},{"id":"PH-H3505-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said college during the fiscal year nineteen hundred sixty-six. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3505-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a Teacher's College in the Municipality of Puerto Princesa, Province of Palawan, to be Known as Palawan Teachers' College, Providing for a Board of Trustees, Defining the Board's Responsibilities and Duties, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3506"] = {"id":"PH-H3506","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4304_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"1949年石油法","en":"Petroleum Act of 1949","orig":"An Act to Repeal Article Forty-Nine of Republic Act Numbered Three Hundred Eighty-Seven, Otherwise Known as the \"Petroleum Act of 1949\"","vi":"Đạo luật Dầu khí năm 1949","th":"พระราชบัญญัติปิโตรเลียม ค.ศ. 1949","id":"Undang-Undang Perminyakan Tahun 1949","ms":"Akta Petroleum 1949"},"level":"law","status":"active","topics":["energy"],"docNumber":"Republic Act No. 4304","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4304_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3506-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Article forty-nine of Republic Act Numbered Three hundred eighty-seven, otherwise known as the \"Petroleum Act of 1949,\" is hereby repealed."}},{"id":"PH-H3506-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Petroleum Act of 1949","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3507"] = {"id":"PH-H3507","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4305_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"授予卡加延省Lallo市镇安装、维护与运营电灯、热力与动力系统特许经营权的法案","en":"An Act Granting the Municipality of Lallo, Province of Cagayan, a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System","orig":"An Act Granting the Municipality of Lallo, Province of Cagayan, a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System","vi":"Đạo luật cấp quyền khai thác cho Municipality of Lallo, Province of Cagayan để xây dựng, lắp đặt, vận hành và duy trì hệ thống điện tại thị xã Lallo, tỉnh Cagayan","th":"พระราชบัญญัติให้สัมปทานแก่ Municipality of Lallo, Province of Cagayan เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบไฟฟ้าในเทศบาล Lallo, จังหวัด Cagayan","id":"Undang-Undang memberikan waralaba kepada Municipality of Lallo, Province of Cagayan untuk membangun, memasang, mengoperasikan, dan memelihara sistem tenaga listrik di Kotamadya Lallo, Provinsi Cagayan","ms":"Akta memberikan francais kepada Municipality of Lallo, Province of Cagayan untuk membina, memasang, mengendalikan dan menyelenggara sistem tenaga elektrik di Perbandaran Lallo, Wilayah Cagayan"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4305","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4305_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3507-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, there is granted to to the Municipality of Lallo, Province of Cagayan, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to install, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the Municipality of Lallo, Province of Cagayan."}},{"id":"PH-H3507-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure electric heat and power from the National Power Corporation, the latter is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H3507-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Municipality of Lallo, Province of Cagayan, a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3508"] = {"id":"PH-H3508","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4306_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Sogod市","en":"An Act Creating the Barrio of Hipantag in the Municipality of Sogod, Province of Southern Leyte","orig":"An Act Creating the Barrio of Hipantag in the Municipality of Sogod, Province of Southern Leyte","vi":"Đạo luật thành lập một Barrio Hipantag tại Đô thị Sogod, Tỉnh Southern Leyte","th":"พระราชบัญญัติจัดตั้งบาริโอ Hipantag ในเทศบาล Sogod จังหวัด Southern Leyte","id":"Undang-Undang membentuk sebuah Barrio Hipantag di Kotamadya Sogod, Provinsi Southern Leyte","ms":"Akta menubuhkan sebuah Barrio Hipantag di Perbandaran Sogod, Wilayah Southern Leyte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4306","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4306_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3508-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Hipantag in the barrio of Benit, Municipality of Sogod, Province of Southern Leyte, is separated from said barrio and constituted into a distinct and independent barrio of said municipality, to be known as the barrio of Hipantag."}},{"id":"PH-H3508-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49"};
  FT["PH-H3509"] = {"id":"PH-H3509","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4307_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《修订行政法典》第271条（最后经第1802号共和国法修正）中关于初审法院法官休假规定的法案","en":"An Act to Amend Section Two Hundred Seventy-One of the Revised Administrative Code, as Last Amended by Republic Act Numbered One Thousand Eighth Hundred Two, Relative to Vacation Leave of Judges of First Instance","orig":"An Act to Amend Section Two Hundred Seventy-One of the Revised Administrative Code, as Last Amended by Republic Act Numbered One Thousand Eighth Hundred Two, Relative to Vacation Leave of Judges of First Instance","vi":"Đạo luật sửa đổi Điều 271 của Đạo luật Cộng hòa số 1000","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 271 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 1000","id":"Undang-Undang mengubah Pasal 271 Undang-Undang Republik No. 1000","ms":"Akta meminda Seksyen 271 Akta Republik No. 1000"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4307","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4307_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3509-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two hundred seventy-one of Act Numbered Two thousand seven hundred eleven, as last amended by Republic Act Numbered One thousand eight hundred two, is hereby further amended to read as follows:\n\"Sec. 271. Leave of Absence of Judges of First Instance.— During the yearly court vacation, the judges of first instance not specially assigned to vacation duty shall be upon vacation leave. In case of those who are assigned to vacation duty, they shall be entitled to vacation leave at any subsequent time for the same number of days that they spend on vacation duty but not exceeding two months per year, one month of said leave being cumulative.\""}},{"id":"PH-H3509-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section Two Hundred Seventy-One of the Revised Administrative Code, as Last Amended by Republic Act Numbered One Thousand Eighth Hundred Two, Relative to Vacation Leave of Judges of First Instance","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3510"] = {"id":"PH-H3510","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4308_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将南伊罗戈省维甘的南伊罗戈省医院收归国有并改设为Gabriela Silang总医院，增加其床位并在其中设立护理与助产学校，同时授权为此拨款的法案","en":"An Act to Nationalize and Convert the Ilocos Sur Provincial Hospital in Vigan, Ilocos Sur, into the Gabriela Silang General Hospital, Increasing its Bed Capacity and Establishing Therein a School of Nursing and Midwifery, and Authorizing the Appropriation of Funds Therefor","orig":"An Act to Nationalize and Convert the Ilocos Sur Provincial Hospital in Vigan, Ilocos Sur, into the Gabriela Silang General Hospital, Increasing its Bed Capacity and Establishing Therein a School of Nursing and Midwifery, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","health"],"docNumber":"Republic Act No. 4308","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4308_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3510-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ilocos Sur Provincial Hospital in Vigan, Ilocos Sur, is hereby converted into a national hospital to be known as the Gabriela Silang General Hospital. The bed capacity of this hospital is increased from fifty to one hundred and fifty beds."}},{"id":"PH-H3510-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There shall be established in the Gabriela Silang General Hospital a school of nursing and midwifery."}},{"id":"PH-H3510-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In addition to the appropriations for said hospital under existing law, the sum of four hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the provisions of this Act for the fiscal year nineteen hundred sixty-five-nineteen hundred sixty-six. Thereafter, the said amounts and such funds as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3510-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Nationalize and Convert the Ilocos Sur Provincial Hospital in Vigan, Ilocos Sur, into the Gabriela Silang General Hospital, Increasing its Bed Capacity and Establishing Therein a School of Nursing and Midwifery, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3511"] = {"id":"PH-H3511","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4309_1965.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"设立Naval市","en":"An Act Converting the Naval High School in the Municipality of Naval, Province of Leyte, into an Institute of Technology, Giving it Corporate Existence, Providing for a Board of Trustees, Defining the Board's Responsibilities and Duties, Providing Higher Vocational, Professional, Educational and Technical Instruction and Training in Trade and Industrial Education, Offering of Technological, Engineering, Education and Other Professional Courses, and for Other Purposes","orig":"An Act Converting the Naval High School in the Municipality of Naval, Province of Leyte, into an Institute of Technology, Giving it Corporate Existence, Providing for a Board of Trustees, Defining the Board's Responsibilities and Duties, Providing Higher Vocational, Professional, Educational and Technical Instruction and Training in Trade and Industrial Education, Offering of Technological, Engineering, Education and Other Professional Courses, and for Other Purposes","vi":"Đạo luật chuyển đổi Naval High School thành Trường trung học phổ thông","th":"พระราชบัญญัติเปลี่ยนสถานะ Naval High School เป็น โรงเรียนมัธยมศึกษา","id":"Undang-Undang mengubah Naval High School menjadi Sekolah Menengah Atas","ms":"Akta menukar Naval High School kepada Sekolah Menengah"},"level":"law","status":"active","topics":["company","trade","education"],"docNumber":"Republic Act No. 4309","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4309_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3511-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The present Naval High School in the Municipality of Naval, Province of Leyte, is hereby converted into an institute of technology to be known as Naval Institute of Technology, which shall offer not only its present four-year secondary trade, four-year technical courses and four-year courses leading to the degrees of Bachelor of Science in Industrial Arts and Bachelor of Science in Industrial Education but also the five-year course leading to the degree of Master of Arts in Industrial Education, the engineering courses leading to the degrees of Bachelor of Science in Civil Engineering, Bachelor of Science in Chemical Engineering, Bachelor of Science in Mechanical Engineering and Bachelor of Science in Electrical Engineering, and as soon as facilities warrant Pharmaceutical, Dental, Commerce, Medical, and Agricultural courses will be offered. Evening classes in the abovementioned courses must be offered."}},{"id":"PH-H3511-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The purpose of said institute of technology shall be to provide higher vocational, professional, and technical instruction and training in trade and industrial education and other vocational courses, professional courses, such as Medicine, Commerce, Pharmacy, Education, Agriculture, and Dentistry and to offer engineering courses to uplift the technological, and potential talents of the youth in his part of the archipelago; and for special purposes to promote research, advance studies and progressive leadership in the field of trade, technical industrial and technological education."}},{"id":"PH-H3511-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The head of this institution shall be known as the President of the Naval Institute of Technology. He shall be appointed by the President of the Philippines upon recommendation of the Board of Trustees, subject to the confirmation of the Commission on Appointments. The powers and duties of the President of the Institute, in addition to those specifically provided for in this Act, shall be those pertaining to the office of the President of a college."}},{"id":"PH-H3511-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The government of the Naval Institute of Technology is hereby vested in a Board of Trustees, to be composed of the Secretary of Education, who shall be ex-officio Chairman of the Board, the Chairman of the Committee on Education of the Senate, the Chairman of the Committee on Education of the House of Representatives, the Director of Public Schools, the President of the Naval Institute of Technology and the President of the Chamber of Industries of the Philippines, as members. In the absence or inability of the Secretary of Education, the Undersecretary of Education shall act as the ex-officio Chairman of the Board. In the absence or inability of both the Secretary and Undersecretary of Education or when those positions are vacant, the other members of the Board may elect from among themselves a temporary chairman who shall act as chairman.\nThe member of the Board of Trustees and Secretary of the Board shall serve without compensation but shall be entitled to reimbursement for actual and necessary expenses incurred either in attendance upon meetings of the Board or upon other official business authorized by resolution of the Board."}},{"id":"PH-H3511-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Board of Trustees shall have the following powers and duties in addition to its general powers of administration:\n(a) To appropriate such sums as may be provided by law for the support of the Institute;\n(b) To confer the degrees of Bachelor of Science in Industrial Arts, Bachelor of Science in Industrial Education, and Master of Arts in Industrial Education to successful candidates for graduation;\n(c) To confer certificates, diplomas or degrees upon successful candidates for graduation;\n(d) To authorize the President of the Institute to award a proficiency certificate to students who have finished the first two years of the four-year curriculum in Technical Education and/or a diploma to those who have completed the four-year curriculum in Technical Education;\n(e) To appoint on recommendation of the President of the Institute, dean of instruction, dean of college, heads of departments, registrar, professors, associate professors, guest lecturers, instructors, teachers and other employees of the college; to fix their compensation, their hours of service and such other duties and conditions as it may deem necessary and proper; to grant them, in its discretion, leave of absence under such regulations as it may promulgate, any provision of law to the contrary notwithstanding, and to remove them for cause after an investigation and hearing shall have been had;\n(f) To approve the curricula and the rules of discipline drawn by the College Council as hereinafter provided;\n(g) To fix as moderately possible, the tuition fees required of students, as well as matriculation fees, graduation fees for laboratory course, and all special fees which shall constitute a special trust for the Institute and to remit such fees in the case of deserving students;\n(h) To provide fellowships for faculty members and scholarships to students showing special evidence of merit;\n(i) To prescribe rules for its own government, and to enact for the government of the Institute such rules and regulations, not contrary to law, as may be necessary to carry out the purposes and functions of the Institute as defined in Section two of this Act; and\n(j) To receive in trust legacies, gifts and donations of real and personal property of all kinds and to administer the same for the benefit of the Institute, or of a department thereof, or for aid to any student or students, in accordance with the directions and instruction of the donor, and, in default thereof, in such manner as the Board of Trustees may in its discretion determine."}},{"id":"PH-H3511-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all members. All processes against the Board of Trustees shall be served on the Chairman or Secretary thereof."}},{"id":"PH-H3511-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"On or before the fifteenth day of June of each year, the Board of Trustees shall file with the President of the Philippines a detailed report, setting forth the progress, condition and needs of the Institute."}},{"id":"PH-H3511-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"There shall be a College Council, consisting of the President of the Institute, dean of instruction, registrar, college dean, department heads, professors, associate professors and of all instructors of the Institute. The Council shall have the power to prescribe the curricula and rules of discipline, subject to the approval of the Board of Trustees. It shall fix the requirements for admission to the Institute, as well as for graduation and the receiving of a title or degree. The Council alone shall have the power to recommend students or others to be recipients of titles or degrees. Through its president or committee, it shall have disciplinary power over the students within limits prescribed by the rules of discipline approved by the Board of Trustees."}},{"id":"PH-H3511-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The body of instructors, professors, associate professors, department heads, college deans, registrar, dean of instruction shall constitute the faculty, with the President of the Institute as the presiding officer. In the appointment of professors, guest professors, guest lecturers, registrar, college dean, department heads, instructors and office personnel of the Institute, no religious test shall be applied, nor shall the religious opinions or affiliation of the faculty of the Institute be a matter of examination or inquiry: Provided, That no instructor/or professor in the Institute shall inculcate sectarian tenets in any of the teaching, nor attempts either directly or indirectly under penalty of dismissal by the Board of Trustees, to influence students or attendants at the Institute for or against any particular church or religious sect."}},{"id":"PH-H3511-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"There shall be a secretary of the Institute to be appointed by the Board of Trustees. He shall be at the same time the secretary of the Board of Trustees and shall keep such records of the Institute or such other duties as may be designated by the Board."}},{"id":"PH-H3511-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The dean of instruction, registrar, college deans, associate professors, professors and other regular instructors in the Institute shall be exempt as such from any civil service examination or regulations as a requisite to appointment."}},{"id":"PH-H3511-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The Board of Trustees shall fix the compensation of the employees and other personnel of the Institute whose appointments will be recommended by the President of the Institute."}},{"id":"PH-H3511-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The President of the Institute, with the cooperation of Division Superintendents and/or Superintendent of Schools of Arts and Trades, may use one or more of their secondary or elementary schools as training or laboratory schools for student-teaching of the Institute."}},{"id":"PH-H3511-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Heads of bureaus and offices of the National Government are hereby authorized to loan or transfer, upon request of the President of the Institute such apparatus, equipment or supplies as may be needed by the Institute, and to detail employees therein for duty, when in the judgment of the head of the bureau or office such apparatus, equipment, supplies or employees can be spared without serious detriment to the public service. Employees so detailed shall perform such duties as are required under such detail and the time so employed shall count as part of their regular service."}},{"id":"PH-H3511-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"In order not to interrupt the smooth functioning of the present curricula of the Naval High School the faculty of the school as well as the other personnel shall be absorbed by the new Institute and their salaries shall be adjusted at the discretion of the Board of Trustees within the amount available for appropriation."}},{"id":"PH-H3511-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The Treasurer of the Philippines shall be ex-officio Treasurer of the Institute and all accounts and expenses thereof shall be audited by the Auditor General or his duly authorized representative."}},{"id":"PH-H3511-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"All the personnel, properties, records and obligations of the Naval High School are hereby transferred to the Naval Institute of Technology."}},{"id":"PH-H3511-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated from the National Treasury for the operation and maintenance of the said institute of technology during the fiscal year nineteen hundred sixty-six. Thereafter, the necessary sum needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3511-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49"};
  FT["PH-H3512"] = {"id":"PH-H3512","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4310_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为高山省增设四名助理省检察官，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Creating Four Additional Positions of Assistant Provincial Fiscal in Mountain Province, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Creating Four Additional Positions of Assistant Provincial Fiscal in Mountain Province, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4310","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4310_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3512-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in Mountain Province, is amended to read as follows:\n\"Mountain Province, six assistant provincial fiscals who shall be assigned to the different branches of the Court of First Instance of Mountain Province in proportion to the number of cases pending in each such branch;\""}},{"id":"PH-H3512-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Four Additional Positions of Assistant Provincial Fiscal in Mountain Province, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3513"] = {"id":"PH-H3513","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4311_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在山区省Pinukpuk市镇设立一所急诊医院并授权为此拨款的法案","en":"An Act Providing for the Establishment of One Emergency Hospital in the Municipality of Pinukpuk, Mountain Province, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of One Emergency Hospital in the Municipality of Pinukpuk, Mountain Province, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Cấp cứu One tại Thị trấn Pinukpuk, Tỉnh Mountain Province, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลฉุกเฉิน One ในเทศบาล Pinukpuk จังหวัด Mountain Province และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Gawat Darurat One di Kotamadya Pinukpuk, Provinsi Mountain Province, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Kecemasan One di Perbandaran Pinukpuk, Wilayah Mountain Province, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4311","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4311_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3513-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Medical Services, one emergency hospital in the Municipality of Pinukpuk, Mountain Province, to be known as Pinukpuk Emergency Hospital."}},{"id":"PH-H3513-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H3513-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said emergency hospital during the fiscal year nineteen hundred sixty-six: Provided, That, thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3513-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of One Emergency Hospital in the Municipality of Pinukpuk, Mountain Province, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3514"] = {"id":"PH-H3514","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4312_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在萨马省阿尔马格罗、达拉姆、圣丽塔、马拉布特与塔朗南各岛市镇分别设立一等药房并授权为此拨款的法案","en":"An Act Providing for the Establishment of a First Class Dispensary in Each of the Island Municipalities of Almagro, DARam, Santa Rita, Marabut and Tarangnan, All in the Province of Samar, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a First Class Dispensary in Each of the Island Municipalities of Almagro, DARam, Santa Rita, Marabut and Tarangnan, All in the Province of Samar, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4312","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4312_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3514-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision of the Director of Health Services a first class dispensary in each of the island municipalities of Almagro, Daram, Santa Rita, Marabut and Tarangnan, all in the Province of Samar, to be known as Almagro Dispensary, Daram Dispensary, Santa Rita Dispensary, Marabut Dispensary and Tarangnan Dispensary, respectively."}},{"id":"PH-H3514-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said dispensaries during the fiscal year nineteen hundred sixty-six: Provided, That each dispensary shall be entitled to twenty thousand pesos. Thereafter, such sums as may be needed for the operation and maintenance of said dispensaries shall be included in the annual General Appropriations Act."}},{"id":"PH-H3514-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a First Class Dispensary in Each of the Island Municipalities of Almagro, DARam, Santa Rita, Marabut and Tarangnan, All in the Province of Samar, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3515"] = {"id":"PH-H3515","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4313_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"规定萨马省Gandara市镇一所医院的运营与维护，名称为Gandara医院，并授权为此拨款的法案","en":"An Act to Provide for the Operation and Maintenance of a Hospital in the Municipality of Gandara, Province of Samar, to be Known as Gandara Hospital, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Provide for the Operation and Maintenance of a Hospital in the Municipality of Gandara, Province of Samar, to be Known as Gandara Hospital, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4313","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4313_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3515-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision of the Director of Medical Services, a twenty-bed capacity hospital in the Municipality of Gandara, Province of Samar, to be known as Gandara Hospital. The site for the said hospital shall be determined by the Municipal Council of the Municipality of Gandara in consultation with the Director of Medical Services."}},{"id":"PH-H3515-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall promulgate such rules and regulations as may be necessary to carry into effect the purposes of this Act."}},{"id":"PH-H3515-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of seventy-five thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said hospital during the fiscal year nineteen hundred sixty-six. Such sums as may be needed for its operation and maintenance in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H3515-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p49","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for the Operation and Maintenance of a Hospital in the Municipality of Gandara, Province of Samar, to be Known as Gandara Hospital, and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
